pattern.example:
# Pattern from test_memory_client.py from unittest.mock import AsyncMock, Mock, patch
@pytest.mark.asyncio async def test_client_method(client_instance): mock_response = Mock() mock_response.status_code = 200 mock_response.json.return_value = {"status": "success"}
with patch.object(client_instance.client, 'post', new_callable=AsyncMock) as mock_post: mock_post.return_value = mock_response
result = await client_instance.method(param1, param2)
# Verify result assert result["status"] == "success"
# Verify POST was called correctly mock_post.assert_called_once() call_args = mock_post.call_args assert call_args[0][0] == "http://expected-url" assert call_args[1]["json"]["field"] == "expected_value"

# Add to requirements.txt: freezegun from freezegun import freeze_time from datetime import datetime
@freeze_time("2025-12-25 10:00:00") def test_scheduled_trigger(): # Time is frozen at 10am # Test cron evaluation, quiet hours check, etc. result = gate.should_fire(trigger, user_id) assert result.allowed is True
@freeze_time("2025-12-25 23:00:00") # 11pm def test_quiet_hours_blocking(): # Time is frozen at 11pm (quiet hours) result = gate.should_fire(trigger, user_id) assert result.allowed is False assert result.reason == "quiet_hours"

# Pattern from test_streaming_e2e.py from unittest.mock import Mock, patch
async def mock_llm_stream(messages, tools=None): yield {"type": "token", "content": "Hello"} yield {"type": "token", "content": " world"} yield {"type": "done", "tokens_used": {"prompt": 10, "completion": 2}}
@pytest.mark.asyncio async def test_agent_execution(): with patch('api.proactive.agent.LLMClient') as MockLLMClient: mock_llm_instance = Mock() MockLLMClient.return_value.__aenter__.return_value = mock_llm_instance mock_llm_instance.chat_completion_stream = mock_llm_stream
# Test agent execution with mocked LLM result = await agent.execute(trigger)
assert result.message == "Hello world"

# backend/tests/test_proactive/conftest.py
import pytest
from unittest.mock import AsyncMock, Mock

@pytest.fixture
def mock_intents_client():
    """Mock IntentsClient for tests."""
    client = AsyncMock()
    client.create_intent = AsyncMock(return_value={"intent_id": "test_123"})
    client.claim_intent = AsyncMock(return_value={"claimed_at": "2025-12-24T10:00:00Z"})
    client.fire_intent = AsyncMock(return_value={"cooldown_active": False})
    return client

@pytest.fixture
def sample_scheduled_trigger():
    """Sample scheduled trigger for testing."""
    return {
        "intent_id": "trigger_123",
        "user_id": "user_456",
        "trigger_type": "scheduled",
        "schedule": {
            "mode": "cron",
            "cron_expression": "0 9 * * 1-5",
            "timezone": "America/Los_Angeles"
        },
        "action_context": {
            "intent_summary": "Daily morning check-in",
            "execution_instructions": "Greet user and ask how they're doing"
        }
    }

@pytest.fixture
def sample_condition_trigger():
    """Sample condition trigger for testing."""
    return {
        "intent_id": "trigger_789",
        "user_id": "user_456",
        "trigger_type": "condition",
        "condition": {
            "type": "price",
            "expression": "NVDA < 130",
            "check_interval_minutes": 5,
            "cooldown_hours": 24
        }
    }
